mapper.select:
SELECT T1.RES_NO
FROM MCP_REQUEST@DL_MCP T1, MCP_REQUEST_OSST@DL_MCP T2
WHERE 1=1
  AND LPAD(T1.RES_NO, 14, '0') = T2.MVNO_ORD_NO
  AND T2.PRGR_STAT_CD = #{prgrStatCd}

    AND T2.RSLT_CD  = #{rsltCd}

  AND T1.REQUEST_KEY = #{requestKey}
  AND ROWNUM = 1

SELECT COUNT(1)
FROM MCP_REQUEST@DL_MCP T1, MCP_REQUEST_OSST@DL_MCP T2
WHERE 1=1
  AND LPAD(#{mvnoOrdNo}, 14, '0') = T2.MVNO_ORD_NO
  AND T2.PRGR_STAT_CD = #{prgrStatCd}

    AND T2.RSLT_CD  = #{rsltCd}

SELECT DISTINCT OSST_ORD_NO
FROM MCP_REQUEST@DL_MCP T1, MCP_REQUEST_OSST@DL_MCP T2
WHERE 1=1
  AND LPAD(#{mvnoOrdNo}, 14, '0') = T2.MVNO_ORD_NO
  AND T2.PRGR_STAT_CD = #{prgrStatCd}

    AND T2.RSLT_CD  = #{rsltCd}

/* mPlatformMapper.getXmlMessageNU1 */ SELECT OSST.OSST_ORD_NO AS osstOrdNo /* OSST 오더번호 */ , A.AGENT_CODE AS asgnAgncId /* 할당대리점ID */ , 'Y' AS asgnAgncYn /* 할당번호조회여부 */ , 'KOR' AS cntryCd /* 국각코드 */ , OSST.CUST_ID AS custNo /* 고객번호 */ , '1' AS inqrBase /* 조회페이지 */ , '10' AS inqrCascnt /* 조회카운트 */ , '03' AS nowSvcIndCd /* 3G */ , '2' AS searchGubun /* 조회구분(1:예약번호, 2:희망번호, 3:Aging) */ , 'GEN' AS tlphNoChrcCd /* 전화번호특성코드 */ , '01' AS tlphNoIndCd /* 전화번호구분코드 */
, DECODE(A.SERVICE_TYPE, 'PP', 'I', 'R') AS tlphNoUseCd /* 번호사용용도코드(R:일반, I:선불) */ , DECODE(A.SERVICE_TYPE, 'PP', 'FUK', '') AS tlphNoUseMntCd /* 선불인경우 */ FROM MCP_REQUEST@DL_MCP A, MCP_REQUEST_OSST@DL_MCP OSST WHERE LPAD(A.RES_NO, 14, '0') = OSST.MVNO_ORD_NO AND OSST.SEQ = (SELECT MAX(SEQ) FROM MCP_REQUEST_OSST@DL_MCP WHERE MVNO_ORD_NO = OSST.MVNO_ORD_NO AND PRGR_STAT_CD = 'PC2' AND RSLT_CD = '0000')
AND A.RES_NO = #{resNo}

SELECT CONTRACT_NUM , SVC_CNTR_NO , T1.SUBSCRIBER_NO , T1.USER_SSN , T1.SUB_LINK_NAME , T2.BL_BILLING_METHOD , T2.BAN , T2.BAN_ADR_ZIP , T2.BAN_ADR_PRIMARY_LN , T2.BAN_ADR_SECONDARY_LN , T1.CUSTOMER_ID , T1.SUB_STATUS , T3.CUSTOMER_TYPE FROM MSP_JUO_SUB_INFO T1 , MSP_JUO_BAN_INFO T2 , MSP_JUO_CUS_INFO T3 WHERE 1=1 AND T1.BAN = T2.BAN AND T1.CUSTOMER_ID = T3.CUSTOMER_ID AND SUB_STATUS <> 'C'
AND SUBSCRIBER_NO= TRIM(#{mobileNo})
AND UPPER(REPLACE(SUB_LINK_NAME,' ','')) = UPPER(REPLACE(#{name},' ',''))
AND CONTRACT_NUM = #{contractNum}
AND T1.CUSTOMER_ID = #{customerId}
